"""Validate authored messages against files generated by pinned Codex.

Requires jsonschema. Validation is static: no connection, no session, no model.
Hook schemas are read from a pinned upstream checkout, never fetched here.
"""
import argparse
import hashlib
import importlib.metadata
import json
from pathlib import Path

from jsonschema import Draft7Validator

from hook_guard import respond

HERE = Path(__file__).resolve().parent


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--schema", type=Path, required=True)
    parser.add_argument("--hooks-schema", type=Path, required=True)
    args = parser.parse_args()
    cases = []
    hashes = {}

    def validator(root, name):
        raw = (root / name).read_bytes()
        hashes[name] = hashlib.sha256(raw).hexdigest()
        schema = json.loads(raw)
        Draft7Validator.check_schema(schema)
        return Draft7Validator(schema)

    messages = json.loads((HERE / "fixtures/app-server-requests.json").read_text(encoding="utf-8"))
    for entry in messages:
        message = entry["message"]
        payload = message.get("params", message.get("result"))
        validator(args.schema, entry["schema"]).validate(payload)
        cases.append({"name": message.get("method", "approval-response"), "passed": True})
    turn = validator(args.schema, "v2/TurnStartParams.json")
    invalid = {"thread_id": "wrong-spelling", "input": []}
    if not list(turn.iter_errors(invalid)):
        raise RuntimeError("missing threadId was accepted")
    cases.append({"name": "reject-thread_id-instead-of-threadId", "passed": True})
    hook_input = validator(args.hooks_schema, "pre-tool-use.command.input.schema.json")
    hook_output = validator(args.hooks_schema, "pre-tool-use.command.output.schema.json")
    for name in ("hook-read.json", "hook-deny.json"):
        event = json.loads((HERE / "fixtures" / name).read_text(encoding="utf-8"))
        hook_input.validate(event)
        hook_output.validate(respond(event))
        cases.append({"name": name + ":input+output", "passed": True})
    event.pop("turn_id")
    if not list(hook_input.iter_errors(event)):
        raise RuntimeError("missing hook turn_id was accepted")
    cases.append({"name": "reject-hook-missing-turn-id", "passed": True})
    print(json.dumps({"date": "2026-11-10", "kind": "static-schema-validation",
                      "source_commit": "086ccc833bc9cf01024ad2dd6af7dbd421b6bf9a",
                      "model_used": False, "connection_started": False,
                      "jsonschema_version": importlib.metadata.version("jsonschema"),
                      "cases": cases, "schemas_sha256": hashes,
                      "inputs_sha256": {p.relative_to(HERE).as_posix(): hashlib.sha256(p.read_bytes()).hexdigest()
                                        for p in (Path(__file__), HERE / "hook_guard.py",
                                                  HERE / "fixtures/app-server-requests.json",
                                                  HERE / "fixtures/hook-read.json",
                                                  HERE / "fixtures/hook-deny.json")},
                      "passed": True}, indent=2))


if __name__ == "__main__":
    main()
